SELECT * FROM ai_child_learning_record 
WHERE child_name = #{childName}
ORDER BY created_at DESC

SELECT * FROM ai_child_learning_record 
WHERE scenario_id = #{scenarioId}
ORDER BY created_at DESC

SELECT * FROM ai_child_learning_record 
WHERE session_id = #{sessionId}
ORDER BY created_at ASC

SELECT * FROM ai_child_learning_record 
WHERE child_name = #{childName} 
AND learning_date BETWEEN #{startDate} AND #{endDate}
ORDER BY learning_date DESC, created_at DESC

SELECT * FROM ai_child_learning_record 
WHERE scenario_id = #{scenarioId} AND child_name = #{childName}
ORDER BY created_at DESC

SELECT COUNT(*) 
FROM ai_child_learning_record 
WHERE child_name = #{childName}

    AND scenario_id = #{scenarioId}
